-- FRANCIS CREATOR STUDIO - 018 Seed 12 Bilingual Tutorials & Guarded Owner Bootstrap

-- 1. Seed the 12 official EN/TE tutorial episodes into public.fcs_tutorials
INSERT INTO public.fcs_tutorials (
  slug,
  episode_number,
  category,
  section_key,
  section_route,
  title_en,
  title_te,
  description_en,
  description_te,
  duration_seconds,
  video_url_en,
  video_url_te,
  thumbnail_url,
  subtitle_vtt_en,
  subtitle_vtt_te,
  transcript_en,
  transcript_te,
  is_published,
  sort_order
)
VALUES
  ('01-website-introduction', 1, 'getting_started', 'home', '/', 'Website Introduction — Exploring Francis Creator Studio', 'వెబ్‌సైట్ పరిచయం — Francis Creator Studio పూర్తి వివరాలు', 'Tour the homepage, main navigation, AI Resume Studio, Certificate Design Studio, Creator AI Assistant, QR verification, and live customer support.', 'హోమ్‌పేజీ, ప్రధాన నావిగేషన్, AI రెజ్యూమ్ స్టూడియో, సర్టిఫికెట్ డిజైన్ స్టూడియో, Creator AI అసిస్టెంట్, QR వెరిఫికేషన్ మరియు సపోర్ట్ ఫీచర్లను తెలుసుకోండి.', 72, '/api/tutorials/stream?file=01-website-introduction-en.mp4', '/api/tutorials/stream?file=01-website-introduction-te.mp4', '/tutorials/01-website-introduction.png', '/tutorials/01-website-introduction-en.vtt', '/tutorials/01-website-introduction-te.vtt', 'Welcome to Creator Studio! Your all-in-one platform for professional resume creation, certificate design, AI assistance and digital verification. Let''s explore every feature and learn how to use this platform. Start right on the homepage, where clean cards and top navigation lead straight to each studio. Open AI Resume Studio to craft structured, ATS-ready resumes with over one hundred layouts. Switch to Certificate Design Studio to browse one hundred twenty-four certificate designs across fourteen categories, customize graphics, and export crisp PDF or PNG files. Meet Creator AI Assistant for instant resume feedback, career roadmaps, and guidance. Check any credential''s authenticity anytime with Public Certificate Verification using a unique code or QR link. And whenever you need a hand, open Live Customer Support for tickets and assistance. Thank you for watching. Visit francis creator studio dot vercel dot app to begin.', 'Creator Studio కి స్వాగతం! ప్రొఫెషనల్ రెజ్యూమ్స్ తయారీ, సర్టిఫికెట్ డిజైన్, AI సహాయం మరియు డిజిటల్ వెరిఫికేషన్ కోసం ఇది ఒక ప్రత్యేకమైన ప్లాట్‌ఫామ్. ఇప్పుడు అన్ని ఫీచర్లను తెలుసుకుందాం. ముందుగా హోమ్‌పేజీలో పై నావిగేషన్ మరియు స్టూడియో కార్డుల ద్వారా ప్రతి విభాగానికి సులభంగా వెళ్లవచ్చు. AI Resume Studio లో వంద టెంప్లేట్లతో ప్రొఫెషనల్ రెజ్యూమ్స్ తయారు చేయండి. Certificate Design Studio లో నూట ఇరవై నాలుగు టెంప్లేట్లతో సర్టిఫికెట్లను డిజైన్ చేయండి. Creator AI Assistant ద్వారా కెరీర్ గైడెన్స్ పొందండి. Public Verification లో QR కోడ్ ద్వారా సర్టిఫికెట్లను చెక్ చేయండి. సహాయం కోసం లైవ్ సపోర్ట్ ఉపయోగించండి.', true, 1),
  ('02-ai-resume-studio', 2, 'studios', 'resume_studio', '/resume-builder/new', 'AI Resume Studio — Build & Export ATS Resumes', 'AI Resume Studio — ప్రొఫెషనల్ రెజ్యూమ్ తయారీ & ఎక్స్‌పోర్ట్', 'Select a template, edit personal info, education, skills, and experience, review ATS readiness, and export PDF or PNG cleanly.', 'నచ్చిన టెంప్లేట్ ఎంచుకుని, వ్యక్తిగత వివరాలు, విద్యార్హతలు, స్కిల్స్ మరియు అనుభవాన్ని నమోదు చేసి PDF లేదా PNG లో ఎక్స్‌పోర్ట్ చేయండి.', 74, '/api/tutorials/stream?file=02-ai-resume-studio-en.mp4', '/api/tutorials/stream?file=02-ai-resume-studio-te.mp4', '/tutorials/02-ai-resume-studio.png', '/tutorials/02-ai-resume-studio-en.vtt', '/tutorials/02-ai-resume-studio-te.vtt', 'Open AI Resume Studio. Enter your personal information, education, skills and experience. Choose your favorite resume template. Review your information and preview your professional resume before exporting. From the template gallery, filter across one hundred distinct layouts built for engineering, academic, executive, and ATS clarity. Click into the live two-panel editor to update your full name, headline, contact links, and career summary while watching the A4 sheet refresh instantaneously. Add degrees inside Education, list technical and soft competencies inside Skills, and record internships or work roles inside Experience. You can drag sections to reorder your layout, edit a profile photo with optional background removal, run transparent ATS quality scoring, and export directly as a crisp print-ready A4 PDF or high-resolution PNG file. Thank you for watching.', 'AI Resume Studio ఓపెన్ చేయండి. మీ వ్యక్తిగత వివరాలు, విద్యార్హతలు, స్కిల్స్ మరియు అనుభవాన్ని నమోదు చేయండి. మీకు నచ్చిన రెజ్యూమ్ టెంప్లేట్ ఎంచుకోండి. ప్రివ్యూ చూసి మీ రెజ్యూమ్‌ను ఎక్స్‌పోర్ట్ చేయండి. గ్యాలరీ నుండి మీ రంగానికి తగిన వంద టెంప్లేట్లలో ఒకటి ఎంచుకోవచ్చు. ఎడిటర్‌లో పేరు, హెడ్‌లైన్, ఈమెయిల్ మరియు సారాంశాన్ని టైప్ చేస్తున్నప్పుడే కుడివైపు లైవ్ ప్రివ్యూ మారుతుంది. విద్యార్హతలు, టెక్నికల్ స్కిల్స్ మరియు పని అనుభవాన్ని సులభంగా జోడించండి. సెక్షన్లను డ్రాగ్ చేసి క్రమాన్ని మార్చండి, ATS స్కోర్ పరిశీలించి హై-క్వాలిటీ A4 PDF లేదా PNG గా డౌన్‌లోడ్ చేసుకోండి.', true, 2),
  ('03-certificate-design-studio', 3, 'studios', 'certificate_studio', '/certificate-builder/new', 'Certificate Design Studio — Customize, Stamp & Publish', 'Certificate Design Studio — సర్టిఫికెట్ డిజైన్ & పబ్లిషింగ్', 'Browse 124 certificate templates across 14 categories, customize typography, borders, signatures, sample stamps, and understand official organization publishing.', '14 విభాగాలలోని 124 సర్టిఫికెట్ టెంప్లేట్ల నుండి ఎంచుకొని, వివరాలు, ఫాంట్లు, సంతకాలు మరియు స్టాంపులను కస్టమైజ్ చేసి ప్రివ్యూ చూడండి.', 76, '/api/tutorials/stream?file=03-certificate-design-studio-en.mp4', '/api/tutorials/stream?file=03-certificate-design-studio-te.mp4', '/tutorials/03-certificate-design-studio.png', '/tutorials/03-certificate-design-studio-en.vtt', '/tutorials/03-certificate-design-studio-te.vtt', 'Welcome to Certificate Design Studio. Select an available certificate template, enter the recipient information and customize your certificate. Preview your final design before publishing. Official organizational certificate features require administrator approval. Begin by picking any design from one hundred twenty-four certificate templates organized across fourteen categories in landscape or portrait orientation. In the Details panel, type the certificate title, recipient name, course or milestone, organization label, issue date, and signatory details. Switch to Design to tune fonts, colors, decorative borders, canvas dimensions, and interactive drag-and-drop layers. Open Stamps and Photos to draw handwritten signatures, upload recipient photos, or place sample watermarked stamps. Export cleanly in 2K or 4K PNG, JPEG, or print PDF, or publish with Verified QR status once your organization is approved by an administrator.', 'Certificate Design Studio ఓపెన్ చేయండి. అందుబాటులో ఉన్న టెంప్లేట్ ఎంచుకోండి. సర్టిఫికెట్ పొందే వ్యక్తి వివరాలను నమోదు చేయండి. డిజైన్‌ను మార్చి ప్రివ్యూ చూడండి. అధికారిక ఆర్గనైజేషన్ సర్టిఫికెట్లకు అడ్మిన్ అనుమతి అవసరం. పద్నాలుగు విభాగాలలో ఉన్న నూట ఇరవై నాలుగు టెంప్లేట్ల నుండి మీకు కావాల్సిన డిజైన్‌ను ఎంచుకోవచ్చు. గ్రహీత పేరు, కోర్సు పేరు, సంస్థ పేరు మరియు సంతకందారు వివరాలను నమోదు చేయండి. రంగులు, బోర్డర్ మరియు ఫాంట్‌ను మార్చి క్యాన్వాస్‌పై ప్రివ్యూ చూడండి. 2K, 4K PNG లేదా PDF లో సేవ్ చేసుకోండి.', true, 3),
  ('04-qr-certificate-verification', 4, 'verification_admin', 'verify', '/verify', 'QR Certificate Verification — Check Credentials Online', 'QR సర్టిఫికెట్ వెరిఫికేషన్ — ఆన్‌లైన్‌లో అసలైన సర్టిఫికెట్ తనిఖీ', 'Verify certificate codes and QR links against the live registry, distinguish Officially Verified from Sample drafts, and report suspicious credentials.', 'Public Certificate Verification ద్వారా QR కోడ్ లేదా సర్టిఫికెట్ ID ఉపయోగించి సర్టిఫికెట్ అసలైనదా కాదా ఆన్‌లైన్‌లో తనిఖీ చేయండి.', 68, '/api/tutorials/stream?file=04-qr-certificate-verification-en.mp4', '/api/tutorials/stream?file=04-qr-certificate-verification-te.mp4', '/tutorials/04-qr-certificate-verification.png', '/tutorials/04-qr-certificate-verification-en.vtt', '/tutorials/04-qr-certificate-verification-te.vtt', 'Use Public Certificate Verification to check a certificate online. Open the verification page, scan its QR code or enter the available verification information. Review the result and certificate details. Every officially issued certificate carries a unique verification code and QR link pointing straight to its live registry entry. Type or scan a certificate ID into the verification search box and press Verify Credential. When valid, the registry clearly confirms Officially Verified status alongside the recipient name, award title, course or achievement, issuing organization, and issue date. Sample or personal drafts are never listed as verified, and revoked certificates display an explicit warning. You can also view approved organizations or submit a suspicious credential report directly for administrator review. Thank you for watching.', 'Public Certificate Verification ద్వారా సర్టిఫికెట్‌ను ఆన్‌లైన్‌లో వెరిఫై చేయవచ్చు. వెరిఫికేషన్ పేజీ ఓపెన్ చేసి QR కోడ్ స్కాన్ చేయండి లేదా అందుబాటులో ఉన్న వివరాలను నమోదు చేయండి. ఫలితాన్ని పరిశీలించండి. ప్రతి అధికారిక సర్టిఫికెట్‌కు ప్రత్యేకమైన కోడ్ మరియు QR లింక్ ఉంటాయి. సెర్చ్ బాక్స్‌లో సర్టిఫికెట్ ID ని నమోదు చేసి Verify క్లిక్ చేయండి. సర్టిఫికెట్ అసలైనదైతే గ్రహీత పేరు, కోర్సు, సంస్థ పేరు మరియు జారీ తేదీ స్పష్టంగా కనిపిస్తాయి. నకిలీ సర్టిఫికెట్లను వెంటనే రిపోర్ట్ చేయవచ్చు.', true, 4),
  ('05-creator-ai-assistant', 5, 'ai_career', 'assistant', '/assistant', 'Creator AI Assistant — Guidance for Resumes & Platform', 'Creator AI Assistant — రెజ్యూమ్, సర్టిఫికెట్లు & టెక్నాలజీ సహాయం', 'Use Creator AI Assistant to ask about platform workflows, resume wording, certificates, and technology topics with interactive follow-up questions.', 'Creator AI Assistant లో మీ ప్రశ్నలు అడిగి రెజ్యూమ్, సర్టిఫికెట్లు, వెబ్‌సైట్ ఫీచర్లు మరియు టెక్నాలజీపై సమాధానాలు పొందండి.', 66, '/api/tutorials/stream?file=05-creator-ai-assistant-en.mp4', '/api/tutorials/stream?file=05-creator-ai-assistant-te.mp4', '/tutorials/05-creator-ai-assistant.png', '/tutorials/05-creator-ai-assistant-en.vtt', '/tutorials/05-creator-ai-assistant-te.vtt', 'Meet Creator AI Assistant. Ask questions about your website, resume creation, certificates, technology and other topics. Enter your question and explore the AI-generated response. Open the AI Assistant from the main navigation bar or click the floating assistant button from any studio page. In the interactive chat panel, click a quick prompt or type a custom question such as how to optimize a software engineering resume summary or choose a certificate border style. Creator AI generates clear, structured, actionable advice tailored to your active document context. You can then ask follow-up questions to refine phrasing, compare technical choices, or request concise bullet points ready to copy into your work. Thank you for watching.', 'Creator AI Assistant ద్వారా మీకు కావాల్సిన ప్రశ్నలు అడగవచ్చు. వెబ్‌సైట్, రెజ్యూమ్, సర్టిఫికెట్లు మరియు టెక్నాలజీ గురించి తెలుసుకోవచ్చు. మీ ప్రశ్న టైప్ చేసి AI సమాధానాన్ని చూడండి. ప్రధాన మెనూ నుండి లేదా ఏ పేజీలోనైనా ఉన్న ఫ్లోటింగ్ బటన్ ద్వారా అసిస్టెంట్‌ను ఓపెన్ చేయండి. మీ సందేహాన్ని లేదా రెజ్యూమ్ సలహా కోసం ప్రశ్నను టైప్ చేసి పంపండి. AI ఇచ్చిన స్పష్టమైన సమాధానాన్ని పరిశీలించి, మరిన్ని ఫాలో-అప్ ప్రశ్నలు అడిగి మీ పనిని సులభంగా పూర్తి చేసుకోండి.', true, 5),
  ('06-career-roadmap-interview-prep', 6, 'ai_career', 'career_roadmap', '/assistant?tab=roadmap', 'Career Roadmap & Interview Preparation Planner', 'Career Roadmap & ఇంటర్వ్యూ ప్రిపరేషన్ ప్లానర్', 'Enter a target job role inside Career Roadmap to explore missing technical skills, learning phases, portfolio project ideas, and interview topics.', 'మీ లక్ష్య ఉద్యోగాన్ని నమోదు చేసి అవసరమైన స్కిల్స్, లెర్నింగ్ దశలు, ప్రాజెక్ట్ ఆలోచనలు మరియు ఇంటర్వ్యూ టాపిక్స్‌ను పొందండి.', 70, '/api/tutorials/stream?file=06-career-roadmap-interview-prep-en.mp4', '/api/tutorials/stream?file=06-career-roadmap-interview-prep-te.mp4', '/tutorials/06-career-roadmap-interview-prep.png', '/tutorials/06-career-roadmap-interview-prep-en.vtt', '/tutorials/06-career-roadmap-interview-prep-te.vtt', 'Plan your future career with Career Roadmap. Enter your target job role and explore recommended skills, learning topics, portfolio ideas and interview preparation. Switch to the Career Roadmap tab inside the AI Assistant workspace. Type your desired target role such as Full-Stack Software Engineer, Cloud Architect, or Data Analyst and list your current skills. Click Generate Roadmap to receive a structured, step-by-step plan grounded in transparent heuristics and your input profile—without fabricated job listings. Review prioritized missing skills, explore a phased learning timeline with concrete outcomes, review portfolio project ideas you can showcase on your resume, and study focused interview preparation topics and internship tips. Thank you for watching.', 'Career Roadmap ద్వారా మీ భవిష్యత్తు కెరీర్‌ను ప్లాన్ చేసుకోండి. మీకు కావాల్సిన ఉద్యోగాన్ని నమోదు చేసి అవసరమైన స్కిల్స్, లెర్నింగ్ టాపిక్స్ మరియు ఇంటర్వ్యూ ప్రిపరేషన్ తెలుసుకోండి. AI అసిస్టెంట్‌లోని Career Roadmap విభాగాన్ని ఓపెన్ చేయండి. మీ టార్గెట్ ఉద్యోగం పేరు మరియు ప్రస్తుత స్కిల్స్ నమోదు చేసి రోడ్‌మ్యాప్ జనరేట్ చేయండి. నేర్చుకోవాల్సిన కొత్త స్కిల్స్, ప్రాజెక్ట్ ఐడియాలు మరియు ఇంటర్వ్యూలో అడిగే ముఖ్యమైన అంశాలను దశలవారీగా తెలుసుకోండి.', true, 6),
  ('07-ai-recommendations', 7, 'ai_career', 'recommendations', '/dashboard?tab=overview', 'AI Recommendations — Improve Your Career Profile', 'AI Recommendations — మీ కెరీర్ ప్రొఫైల్‌ను మెరుగుపరుచుకోండి', 'Review opt-in workspace AI suggestions on your Studio Hub Dashboard, inspect why each recommendation appeared, and apply improvements safely.', 'డాష్‌బోర్డ్‌లోని AI సూచనలను పరిశీలించి, వాటి కారణాన్ని తెలుసుకుని మీ రెజ్యూమ్ మరియు కెరీర్ ప్రొఫైల్‌ను మెరుగుపరచుకోండి.', 66, '/api/tutorials/stream?file=07-ai-recommendations-en.mp4', '/api/tutorials/stream?file=07-ai-recommendations-te.mp4', '/tutorials/07-ai-recommendations.png', '/tutorials/07-ai-recommendations-en.vtt', '/tutorials/07-ai-recommendations-te.vtt', 'Discover AI recommendations to improve your professional profile. Review the available suggestions and use them to improve your resume and career preparation. Open your Studio Hub Dashboard and look at the Creator AI Recommendations panel on the Overview tab. Nothing ever changes automatically without your approval. Click Analyze Workspace to evaluate your saved resumes and credentials and generate prioritized suggestions. Expand Why on any card to inspect the exact rationale behind the tip, mark suggestions helpful, bookmark items for later, or click Open and Apply to jump directly to the relevant builder section and strengthen your career profile. You can also toggle recommendations on or off anytime. Thank you for watching.', 'మీ ప్రొఫెషనల్ ప్రొఫైల్‌ను మెరుగుపరచడానికి AI సూచనలను ఉపయోగించండి. అందుబాటులో ఉన్న సూచనలను పరిశీలించి మీ రెజ్యూమ్ మరియు కెరీర్ ప్రిపరేషన్‌ను మెరుగుపరచుకోండి. మీ డాష్‌బోర్డ్ ఓపెన్ చేసి Creator AI Recommendations విభాగాన్ని చూడండి. Analyze Workspace క్లిక్ చేయడం ద్వారా మీ సేవ్ చేసిన రెజ్యూమ్స్ ఆధారంగా కొత్త సూచనలు వస్తాయి. ప్రతి సూచన వెనుక ఉన్న కారణాన్ని చూసి మీ అనుమతితో మాత్రమే మీ ప్రొఫైల్‌లో మార్పులు చేసుకోండి.', true, 7),
  ('08-conversations-chat-sessions', 8, 'ai_career', 'conversations', '/assistant', 'Conversations & Chat Sessions — Organize AI Topics', 'చాట్ సెషన్లు & హిస్టరీ — ప్రతి అంశానికి ప్రత్యేక సంభాషణ', 'Create separate AI chat sessions for resumes, certificates, or technical study, switch seamlessly between topics, and revisit conversation history.', 'రెజ్యూమ్స్, సర్టిఫికెట్లు లేదా ఇతర అంశాల కోసం వేర్వేరు చాట్ సెషన్లు ప్రారంభించి పాత సంభాషణలను తిరిగి చూడండి.', 65, '/api/tutorials/stream?file=08-conversations-chat-sessions-en.mp4', '/api/tutorials/stream?file=08-conversations-chat-sessions-te.mp4', '/tutorials/08-conversations-chat-sessions.png', '/tutorials/08-conversations-chat-sessions-en.vtt', '/tutorials/08-conversations-chat-sessions-te.vtt', 'Start separate conversations for different topics. Click New Chat Session, enter your question and continue your discussion. Use the available history features to revisit previous conversations. Inside Creator AI, keeping separate sessions prevents resume brainstorming from mixing with certificate design or interview prep. View your saved conversation threads in the session sidebar whenever you are signed in, switch between active contexts with one click, or start a clean slate by pressing New Chat Session. Every message stays organized by topic so you can jump back in days later, pick up your discussion right where you paused, and review previous AI answers anytime. Thank you for watching.', 'వేర్వేరు విషయాల కోసం ప్రత్యేకమైన చాట్ సెషన్లు ప్రారంభించండి. New Chat Session క్లిక్ చేసి మీ ప్రశ్న అడగండి. అందుబాటులో ఉన్న హిస్టరీ ఫీచర్ల ద్వారా పాత సంభాషణలను తిరిగి చూడండి. ఒకే చాట్‌లో అన్ని ప్రశ్నలు కలపకుండా రెజ్యూమ్ సలహాలు, సర్టిఫికెట్ డిజైన్ మరియు ఇంటర్వ్యూ ప్రిపరేషన్ కోసం వేర్వేరు సెషన్లు ఉంచండి. సైడ్‌బార్‌లోని హిస్టరీ జాబితా నుండి ఎప్పుడైనా పాత చాట్‌ను ఓపెన్ చేసి కొనసాగించవచ్చు.', true, 8),
  ('09-live-support-tickets', 9, 'verification_admin', 'support', '/support', 'Live Support & Tickets — Get Help Fast', 'Live Support & Tickets — సమస్యలకు తక్షణ సహాయం', 'Submit structured support tickets, select issue categories and priorities, attach screenshots, or track live support responses directly in one place.', 'మీ సమస్యకు తగిన కేటగిరీ ఎంచుకుని, వివరాలు మరియు స్క్రీన్‌షాట్లతో సపోర్ట్ టికెట్‌ను సమర్పించి స్టేటస్‌ను ట్రాక్ చేయండి.', 68, '/api/tutorials/stream?file=09-live-support-tickets-en.mp4', '/api/tutorials/stream?file=09-live-support-tickets-te.mp4', '/tutorials/09-live-support-tickets.png', '/tutorials/09-live-support-tickets-en.vtt', '/tutorials/09-live-support-tickets-te.vtt', 'Need assistance? Open Live Support and Tickets. Explain your problem, provide the required details and submit your support request. Follow the available support process to receive assistance. Visit the Support page from the top menu. Choose your issue category—such as Resume Builder, Certificate Builder, Verification, Account Auth, or Bug Report—along with priority level and channel. Write a clear subject line and concise description, optionally attach a helpful screenshot, and submit your ticket. Every created ticket receives a structured reference number and status tracker so you can read staff replies, add follow-up messages, and resolve your issue smoothly from start to finish. Thank you for watching.', 'మీకు సహాయం కావాలంటే Live Support and Tickets ఓపెన్ చేయండి. మీ సమస్యను వివరించి అవసరమైన వివరాలు నమోదు చేసి సపోర్ట్ రిక్వెస్ట్ సబ్మిట్ చేయండి. పై మెనూ నుండి Support పేజీలోకి వెళ్లండి. సమస్యకు సంబంధించిన కేటగిరీ, ప్రాధాన్యత మరియు ఛానల్‌ను ఎంచుకోండి. స్పష్టమైన వివరణ రాసి అవసరమైతే స్క్రీన్‌షాట్ జత చేసి సమర్పించండి. ప్రతి టికెట్‌కు ఒక ప్రత్యేక నంబర్ లభిస్తుంది మరియు సపోర్ట్ టీమ్ ఇచ్చే సమాధానాలను అక్కడే చూడవచ్చు.', true, 9),
  ('10-authorized-organizations', 10, 'verification_admin', 'authorized_orgs', '/stamps', 'Authorized Organizations & Official Stamp Approvals', 'అనుమతి పొందిన సంస్థలు & అధికారిక స్టాంప్ హక్కులు', 'Understand how institutions apply for Authorized Organization verification, pass administrator review, and unlock Official Stamps, Bulk Issuance, and Verified QR publishing.', 'సంస్థలు Authorized Organization కోసం ఎలా దరఖాస్తు చేసుకోవాలి, అడ్మిన్ అనుమతితో అధికారిక స్టాంపులు మరియు QR సర్టిఫికెట్లను ఎలా పొందాలో తెలుసుకోండి.', 70, '/api/tutorials/stream?file=10-authorized-organizations-en.mp4', '/api/tutorials/stream?file=10-authorized-organizations-te.mp4', '/tutorials/10-authorized-organizations.png', '/tutorials/10-authorized-organizations-en.vtt', '/tutorials/10-authorized-organizations-te.vtt', 'Francis Creator Studio offers special certificate features for authorized organizations. Organization approval is required before accessing restricted certificate and official stamp functionality. While anyone can craft personal designs using Sample Mode and sample watermarked stamps, official seals without sample watermarks and live Verified QR credentials are strictly protected to prevent impersonation. Educational institutions, academies, and companies submit their organization name, contact email, and domain on the Verify page. Administrators verify each application inside the Admin Console. Once approved, your account immediately unlocks the Official Organization Stamp Studio, custom organizational seals, Bulk CSV and Excel credential issuance, and Officially Verified public QR links. Thank you for watching.', 'Francis Creator Studio లో అనుమతి పొందిన ఆర్గనైజేషన్ల కోసం ప్రత్యేకమైన సర్టిఫికెట్ ఫీచర్లు ఉన్నాయి. ఈ ఫీచర్లను ఉపయోగించడానికి అడ్మిన్ అనుమతి అవసరం. సాధారణ వినియోగదారులు శాంపిల్ మోడ్‌లో స్వేచ్ఛగా డిజైన్లు చేసుకోవచ్చు. కానీ నకిలీ సర్టిఫికెట్లను నివారించడానికి అధికారిక సంస్థల స్టాంపులు మరియు లైవ్ QR వెరిఫికేషన్ కేవలం వెరిఫైడ్ సంస్థలకు మాత్రమే అందుబాటులో ఉంటాయి. Verify పేజీలో మీ సంస్థ వివరాలతో దరఖాస్తు చేసుకుని అడ్మిన్ అనుమతి పొందిన తర్వాత అధికారిక స్టాంప్ స్టూడియో మరియు బల్క్ జారీ ఫీచర్లు ఓపెన్ అవుతాయి.', true, 10),
  ('11-document-vault', 11, 'studios', 'document_vault', '/vault', 'Document Vault — Secure Cloud Access & Downloads', 'Document Vault — సేవ్ చేసిన డాక్యుమెంట్ల సురక్షిత నిర్వహణ', 'Locate Document Vault from your Dashboard or navigation, inspect saved exports, uploaded photos, stamps, and manage secure private signed downloads.', 'డాష్‌బోర్డ్ మరియు Document Vault ద్వారా మీ సేవ్ చేసిన PDFలు, ఫోటోలు, లోగోలు మరియు ఇతర ఫైళ్లను సురక్షితంగా యాక్సెస్ చేయండి.', 66, '/api/tutorials/stream?file=11-document-vault-en.mp4', '/api/tutorials/stream?file=11-document-vault-te.mp4', '/tutorials/11-document-vault.png', '/tutorials/11-document-vault-en.vtt', '/tutorials/11-document-vault-te.vtt', 'Document Vault helps users access their saved documents. Open the available dashboard, review your documents and use the supported file management features. Every signed-in creator receives private storage organized across saved resumes, certificates, personal design projects, exported PDFs, profile photos, and logos. Open your Studio Hub Dashboard or navigate directly to Document Vault to see every stored file sorted cleanly with file size, asset category, and timestamp. Each file uses private owner-scoped signed download URLs so unauthorized visitors can never access your personal exports or uploads. Click Download to retrieve a signed copy anytime, upload new reusable assets directly, or delete files you no longer want stored. Thank you for watching.', 'Document Vault ద్వారా మీరు సేవ్ చేసిన డాక్యుమెంట్లను యాక్సెస్ చేసుకోవచ్చు. డాష్‌బోర్డ్ ఓపెన్ చేసి మీ డాక్యుమెంట్లను పరిశీలించండి. సైన్ ఇన్ చేసిన ప్రతి యూజర్‌కు వారి రెజ్యూమ్స్, సర్టిఫికెట్లు, ఎక్స్‌పోర్ట్ చేసిన PDFలు, ఫోటోలు మరియు లోగోలు ప్రైవేట్ స్టోరేజ్‌లో భద్రంగా ఉంటాయి. మీకు అవసరమైన ఫైళ్లను ప్రైవేట్ సైన్డ్ లింకుల ద్వారా సురక్షితంగా డౌన్‌లోడ్ చేసుకోవచ్చు లేదా అవసరం లేని ఫైళ్లను తొలగించవచ్చు.', true, 11),
  ('12-admin-dashboard', 12, 'verification_admin', 'admin_dashboard', '/admin', 'Admin Dashboard — Platform Settings, Approvals & Tutorials', 'Admin Dashboard — అడ్మిన్ సెట్టింగ్స్, అనుమతులు & ట్యుటోరియల్ నిర్వహణ', 'Walk through the dedicated Staff & Admin Console login, review platform settings, safely save and verify configuration updates, and oversee operations.', 'అధీకృత అడ్మిన్ పోర్టల్ లో లాగిన్ అయ్యి ప్లాట్‌ఫామ్ సెట్టింగ్స్, సంస్థల అనుమతులు మరియు ట్యుటోరియల్స్‌ను సురక్షితంగా నిర్వహించండి.', 70, '/api/tutorials/stream?file=12-admin-dashboard-en.mp4', '/api/tutorials/stream?file=12-admin-dashboard-te.mp4', '/tutorials/12-admin-dashboard.png', '/tutorials/12-admin-dashboard-en.vtt', '/tutorials/12-admin-dashboard-te.vtt', 'Welcome to Admin Dashboard. Authorized administrators can manage platform settings and available administrative features. Review the settings carefully and verify every change. Sign in through the dedicated Admin Console login—strictly isolated from regular customer accounts using role-based access control. Inside the console, administrators oversee organization verification approvals, reported certificate moderation, template and category publishing, support tickets, tutorial video management, and core platform settings. Navigate to Security and Platform Settings to review active AI, storage, and safety controls. Adjust a setting safely, click Save Changes, confirm the audit-logged confirmation toast, and verify your updated state across the dashboard and live platform. Thank you for watching.', 'Admin Dashboard ద్వారా అనుమతి పొందిన అడ్మిన్లు ప్లాట్‌ఫామ్ సెట్టింగ్స్‌ను నిర్వహించవచ్చు. అవసరమైన మార్పులు చేసి వాటిని సేవ్ చేసి వెరిఫై చేయండి. కేవలం అధీకృత స్టాఫ్ మరియు అడ్మిన్ ఖాతాలతో మాత్రమే Admin Console లో లాగిన్ కాగలరు. ఇక్కడ సంస్థల వెరిఫికేషన్ అనుమతులు, రిపోర్ట్ అయిన సర్టిఫికెట్లు, టెంప్లేట్లు, వీడియో ట్యుటోరియల్స్ మరియు ప్లాట్‌ఫామ్ సెట్టింగ్స్‌ను నిర్వహించవచ్చు. మార్పులు సేవ్ చేసిన తర్వాత ప్రతి అప్‌డేట్‌ను సరిగ్గా వెరిఫై చేసుకోండి.', true, 12)
ON CONFLICT (slug) DO UPDATE SET
  episode_number = EXCLUDED.episode_number,
  category = EXCLUDED.category,
  section_key = EXCLUDED.section_key,
  section_route = EXCLUDED.section_route,
  title_en = EXCLUDED.title_en,
  title_te = EXCLUDED.title_te,
  description_en = EXCLUDED.description_en,
  description_te = EXCLUDED.description_te,
  duration_seconds = EXCLUDED.duration_seconds,
  video_url_en = COALESCE(NULLIF(public.fcs_tutorials.video_url_en, ''), EXCLUDED.video_url_en),
  video_url_te = COALESCE(NULLIF(public.fcs_tutorials.video_url_te, ''), EXCLUDED.video_url_te),
  thumbnail_url = COALESCE(NULLIF(public.fcs_tutorials.thumbnail_url, ''), EXCLUDED.thumbnail_url),
  subtitle_vtt_en = COALESCE(NULLIF(public.fcs_tutorials.subtitle_vtt_en, ''), EXCLUDED.subtitle_vtt_en),
  subtitle_vtt_te = COALESCE(NULLIF(public.fcs_tutorials.subtitle_vtt_te, ''), EXCLUDED.subtitle_vtt_te),
  transcript_en = COALESCE(NULLIF(public.fcs_tutorials.transcript_en, ''), EXCLUDED.transcript_en),
  transcript_te = COALESCE(NULLIF(public.fcs_tutorials.transcript_te, ''), EXCLUDED.transcript_te),
  is_published = EXCLUDED.is_published,
  sort_order = EXCLUDED.sort_order;

-- 2. Guarded Super Admin bootstrap for verified platform owner when no super_admin exists yet
CREATE OR REPLACE FUNCTION public.fcs_auto_grant_owner_super_admin()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  IF lower(trim(coalesce(NEW.email, ''))) = 'yadlapallif@gmail.com'
     AND NOT EXISTS (SELECT 1 FROM public.fcs_user_roles WHERE role = 'super_admin')
     AND EXISTS (
       SELECT 1 FROM auth.users u
       WHERE u.id = NEW.id AND u.email_confirmed_at IS NOT NULL
     ) THEN
    INSERT INTO public.fcs_user_roles (user_id, role)
    VALUES
      (NEW.id, 'super_admin'),
      (NEW.id, 'customer')
    ON CONFLICT (user_id, role) DO NOTHING;

    UPDATE public.fcs_profiles
    SET headline = COALESCE(NULLIF(trim(headline), ''), 'Creator & Super Administrator')
    WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_fcs_auto_grant_owner_super_admin ON public.fcs_profiles;
CREATE TRIGGER trg_fcs_auto_grant_owner_super_admin
  AFTER INSERT OR UPDATE OF email, last_active_at ON public.fcs_profiles
  FOR EACH ROW
  EXECUTE FUNCTION public.fcs_auto_grant_owner_super_admin();
